using System;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class SleepRecoveryTests
    {
        static NeedsData Tired()=>new NeedsData{Sleep=0,Stamina=5,StaminaCooldown=5000,Hunger=45,Thirst=67,LastConsumptionId="food",Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"Future",42}}};
        [Fact] public void TenSecondsWakeFullOnceWithoutChangingFoodOrReceipt()
        {var d=Tired();int writes=0;Assert.True(SleepRecoveryRules.Begin(ref d,"one",n=>writes++));for(int i=0;i<9;i++)SleepRecoveryRules.Advance(d,1000,true);Assert.False(SleepRecoveryRules.Wake(ref d,n=>throw new Exception()));Assert.Equal(1000,d.SleepRecovery.Remaining);SleepRecoveryRules.Advance(d,1000,true);Assert.True(SleepRecoveryRules.Wake(ref d,n=>writes++));Assert.Equal(100,d.Sleep);Assert.Equal(100,d.Stamina);Assert.Equal(0,d.StaminaCooldown);Assert.Null(d.SleepRecovery);Assert.Equal(45,d.Hunger);Assert.Equal(67,d.Thirst);Assert.Equal("food",d.LastConsumptionId);Assert.Equal(42,(int)d.Extra["Future"]);Assert.False(SleepRecoveryRules.Begin(ref d,"two",n=>throw new Exception()));Assert.False(SleepRecoveryRules.Wake(ref d,n=>throw new Exception()));Assert.Equal(2,writes);}
        [Fact] public void FailedBeginDoesNotAllowUnrecordedRecovery(){var d=Tired();var old=d;Assert.Throws<InvalidOperationException>(()=>SleepRecoveryRules.Begin(ref d,"one",n=>throw new InvalidOperationException()));Assert.Same(old,d);Assert.Null(d.SleepRecovery);Assert.Equal(0,d.Sleep);}
        [Fact] public void FailedWakeKeepsFinishedEpisodeForRetryWithoutRestart(){var d=Tired();SleepRecoveryRules.Begin(ref d,"one",n=>{});SleepRecoveryRules.Advance(d,1000,true);for(int i=0;i<9;i++)SleepRecoveryRules.Advance(d,1000,true);var old=d;Assert.Throws<InvalidOperationException>(()=>SleepRecoveryRules.Wake(ref d,n=>throw new InvalidOperationException()));Assert.Same(old,d);Assert.Equal(0,d.SleepRecovery.Remaining);Assert.False(SleepRecoveryRules.Begin(ref d,"two",n=>throw new Exception()));Assert.True(SleepRecoveryRules.Wake(ref d,n=>{}));Assert.Equal(100,d.Sleep);}
        [Theory] [InlineData(false,1000)] [InlineData(true,1001)] [InlineData(true,-1)] [InlineData(true,30000)]
        public void PauseAndStallDoNotCompleteRecovery(bool active,int dt){var d=Tired();SleepRecoveryRules.Begin(ref d,"one",n=>{});SleepRecoveryRules.Advance(d,dt,active);Assert.Equal(10000,d.SleepRecovery.Remaining);}
        [Fact] public void ReloadRetainsRemainingTimeAndMetadata(){var d=Tired();SleepRecoveryRules.Begin(ref d,"one",n=>{});for(int i=0;i<6;i++)SleepRecoveryRules.Advance(d,1000,true);d.SleepRecovery.Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"Future",true}};d=JsonConvert.DeserializeObject<NeedsData>(JsonConvert.SerializeObject(d));Assert.Equal(4000,d.SleepRecovery.Remaining);Assert.True((bool)d.SleepRecovery.Extra["Future"]);for(int i=0;i<4;i++)SleepRecoveryRules.Advance(d,1000,true);Assert.True(SleepRecoveryRules.Wake(ref d,n=>{}));}
        [Theory] [InlineData("vehicle")] [InlineData("entering")] [InlineData("water")] [InlineData("air")] [InlineData("combat")] [InlineData("ragdoll")] [InlineData("mission")] [InlineData("wanted")] [InlineData("menu")] [InlineData("control")] [InlineData("dead")] [InlineData("animal")] [InlineData("foot")] [InlineData("speed")]
        public void UnsafeContextsNeverStartCollapse(string reason)=>Assert.False(SleepRecoveryRules.Safe(reason!="animal",reason!="dead",reason!="foot",reason=="vehicle",reason=="entering",reason=="water",reason=="air",reason=="combat",reason=="ragdoll",reason=="mission",reason=="wanted",reason=="menu",reason!="control",reason=="speed"?2:0));
        [Fact] public void SafeFootCanRecover(){Assert.True(SleepRecoveryRules.Safe(true,true,true,false,false,false,false,false,false,false,false,false,true,1));Assert.False(SleepRecoveryRules.Safe(true,true,true,false,false,false,false,false,false,false,false,false,true,float.NaN));}
        [Fact] public void NativeBedRestoresWithoutNeedingACollapse(){var d=Tired();d.Sleep=20;Assert.True(SleepRecoveryRules.Wake(ref d,n=>{},true));Assert.Equal(100,d.Sleep);Assert.Equal(45,d.Hunger);Assert.Equal(67,d.Thirst);Assert.Equal(100,d.Stamina);}
        [Fact] public void PendingFoodRecoveryCannotUndoSleepFromBed(){var d=Tired();var receipt=NeedsRules.Food(d,"later-food",35,0);Assert.Equal(0,receipt.Sleep);SleepRecoveryRules.Wake(ref d,n=>{},true);Assert.True(NeedsRules.Apply(ref d,receipt,n=>{}));Assert.Equal(100,d.Sleep);Assert.Equal(100,d.Stamina);Assert.Equal(80,d.Hunger);}
        [Fact] public void NativeSleepRecognizesSceneAndClockJumpExactlyOnce(){var m=new NativeBedSleepMeter();Assert.False(m.Observe(480,16,true,false,false));Assert.False(m.Observe(480,16,true,true,false));Assert.True(m.Observe(960,1500,true,false,false));Assert.False(m.Observe(960,16,true,false,false));}
        [Fact] public void MidnightSleepIsRecognized(){var m=new NativeBedSleepMeter();m.Observe(1080,16,true,true,false);Assert.True(m.Observe(120,2000,true,false,false));}
        [Fact] public void SameFrameFadeAndSleepClockJumpIsRecognized(){var m=new NativeBedSleepMeter();m.Observe(480,16,true,false,false);Assert.True(m.Observe(960,1000,true,true,false));}
        [Theory] [InlineData(false,true,false)] [InlineData(true,false,false)] [InlineData(true,true,true)]
        public void NoFreeRecoveryFromTravelPlainClockOrExcludedCommands(bool home,bool scene,bool excluded){var m=new NativeBedSleepMeter();m.Observe(480,16,home,scene,excluded);Assert.False(m.Observe(960,1000,home,false,excluded));}
        [Fact] public void ReverseAndExcessiveTimeChangesDoNotCount(){var m=new NativeBedSleepMeter();m.Observe(720,16,true,true,false);Assert.False(m.Observe(700,16,true,false,false));m.Reset();m.Observe(100,16,true,true,false);Assert.False(m.Observe(1100,1000,true,false,false));}
        [Fact] public void LongOfflineGapAndInvalidClockResetProof(){var m=new NativeBedSleepMeter();m.Observe(480,16,true,true,false);Assert.False(m.Observe(960,120001,true,false,false));m.Observe(480,16,true,true,false);Assert.False(m.Observe(-1,16,true,false,false));Assert.False(m.Observe(960,16,true,false,false));}
        [Fact] public void CorruptRecoveryIsNotOverwritten(){var d=Tired();d.SleepRecovery=new SleepRecovery{Id="one",Remaining=-1};Assert.False(SleepRecoveryRules.Wake(ref d,n=>throw new Exception(),true));Assert.False(SleepRecoveryRules.Begin(ref d,"two",n=>throw new Exception()));Assert.Equal(-1,d.SleepRecovery.Remaining);}
    }
}
